import{importJWK}from"../key/import.js";import{isObject}from"../lib/type_checks.js";import{JWSInvalid}from"../util/errors.js";export async function EmbeddedJWK(e,t){const r={...e,...t?.header};if(!isObject(r.jwk))throw new JWSInvalid('"jwk" (JSON Web Key) Header Parameter must be a JSON object');const i=await importJWK({...r.jwk,ext:!0},r.alg);if(i instanceof Uint8Array||"public"!==i.type)throw new JWSInvalid('"jwk" (JSON Web Key) Header Parameter must be a public key');return i}